import itertools
import random
import re

MOD = 998244353
SMALL_CASES = (
    ("?",),
    ("1",),
    ("11",),
    ("2", "2"),
    ("123", "312"),
    ("123", "3?1"),
    ("1?", "??"),
    ("??", "??"),
    ("?1?2?3??",),
    ("?", "?", "?", "?", "?", "?", "?", "?"),
    ("12", "21"),
    ("1?2", "?3?"),
    ("???", "???", "???"),
)


def _parse(inp):
    lines = inp.splitlines()
    if not lines:
        return None
    header = lines[0].split()
    if len(header) != 2:
        return None
    dims = []
    for token in header:
        if re.fullmatch(r"\+?[0-9]+", token) is None:
            return None
        digits = token.lstrip("+").lstrip("0")
        if not digits or len(digits) > 3:
            return None
        dims.append(int(digits))
    h, w = dims
    if h * w > 200 or len(lines) != h + 1:
        return None
    rows = lines[1:]
    if any(len(row) != w or any(c not in "123?" for c in row)
           for row in rows):
        return None
    return h, w, rows


def _format(rows):
    return f"{len(rows)} {len(rows[0])}\n" + "\n".join(rows) + "\n"


def _fixed_conflict(rows, h, w):
    for i in range(h):
        for j in range(w):
            c = rows[i][j]
            if c != "?":
                if j + 1 < w and c == rows[i][j + 1]:
                    return True
                if i + 1 < h and c == rows[i + 1][j]:
                    return True
    return False


def validate_input(inp: str) -> bool:
    return _parse(inp) is not None


def gen_small(seed: int, n: int) -> list[str]:
    rng = random.Random(seed)
    result = []
    for k in range(n):
        if k < len(SMALL_CASES):
            rows = SMALL_CASES[k]
        else:
            h = rng.randint(1, 8)
            w = rng.randint(1, min(8, 9 // h))
            alphabet = rng.choice(("123?", "123????", "123", "?"))
            rows = [
                "".join(rng.choice(alphabet) for _ in range(w))
                for _ in range(h)
            ]
        result.append(_format(rows))
    return result


def gen_stress(seed: int) -> list[str]:
    return [
        _format(("?" * 14,) * 14),
        _format(("?" * 200,)),
    ]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    parsed = _parse(inp)
    if parsed is None:
        return [("POST-1", "Input does not match the grid format or bounds.")]
    tokens = out.split()
    if len(tokens) != 1 or re.fullmatch(r"[+-]?[0-9]+", tokens[0]) is None:
        return [("POST-3", "Expected exactly one decimal integer token.")]

    token = tokens[0]
    digits = token.lstrip("+-").lstrip("0") or "0"
    if len(digits) > 9 or (token.startswith("-") and digits != "0"):
        return [("POST-3", "The integer is outside the residue range.")]
    value = int(digits)
    if value >= MOD:
        return [("POST-3", "The integer is outside the residue range.")]

    h, w, rows = parsed
    q = sum(row.count("?") for row in rows)
    errors = []
    if value > 3 ** q:
        errors.append(("POST-3", "The residue exceeds the number of replacements."))
    if _fixed_conflict(rows, h, w):
        if value != 0:
            errors.append(("POST-4", "Equal fixed neighbors force a zero count."))
    elif q == 0:
        if value != 1:
            errors.append(("POST-4", "A valid fully fixed grid has count one."))
    elif h == w == 1 and value != 3:
        errors.append(("POST-4", "A single question mark has count three."))
    return errors


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    result = []
    for k, inp in enumerate(gen_small(seed, n)):
        _, _, rows = _parse(inp)
        mode = k % 4
        if mode == 0:
            transformed = ["".join(col) for col in zip(*rows)]
        elif mode == 1:
            transformed = [row[::-1] for row in rows]
        elif mode == 2:
            transformed = rows[::-1]
        else:
            mapping = {"1": "2", "2": "3", "3": "1", "?": "?"}
            transformed = ["".join(mapping[c] for c in row) for row in rows]
        other = _format(transformed)
        if other != inp:
            result.append(("POST-5", "equal", inp, other))
    return result


def reference_small(inp: str) -> str | None:
    parsed = _parse(inp)
    if parsed is None:
        return None
    h, w, rows = parsed
    cells = "".join(rows)
    unknown = [i for i, c in enumerate(cells) if c == "?"]
    if h * w > 24 or h * w * 3 ** len(unknown) > 400_000:
        return None

    count = 0
    for replacement in itertools.product("123", repeat=len(unknown)):
        filled = list(cells)
        for i, digit in zip(unknown, replacement):
            filled[i] = digit
        if all(
            (j + 1 == w or filled[i * w + j] != filled[i * w + j + 1])
            and (i + 1 == h or filled[i * w + j] != filled[(i + 1) * w + j])
            for i in range(h)
            for j in range(w)
        ):
            count += 1
    return str(count % MOD) + "\n"
